function createStore(initial) {
  let state = { ...initial };
  const subs = new Set();
  return {
    getState: () => state,
    set(patch) {
      const prev = state;
      state = { ...state, ...patch };
      for (const { selector, listener } of subs) {
        const a = selector(prev);
        const b = selector(state);
        if (!Object.is(a, b)) listener(b, a);
      }
    },
    subscribe(selector, listener) {
      const sub = { selector, listener };
      subs.add(sub);
      return () => subs.delete(sub);
    },
  };
}

const store = createStore({ user: { name: "Ray" }, cartCount: 0, theme: "dark" });
store.subscribe(
  (s) => s.cartCount,
  (next, prev) => console.log(`cart badge: ${prev} -> ${next} (re-render badge)`)
);
store.subscribe(
  (s) => s.user,
  (next) => console.log(`user menu: re-render (user is ${next.name})`)
);

console.log("--- set user.name (unrelated slice) ---");
store.set({ user: { name: "Raymond" } });
console.log("--- set cartCount 0 -> 2 ---");
store.set({ cartCount: 2 });
console.log("--- set theme (nobody selected it) ---");
store.set({ theme: "light" });

