function channel() {
  const listeners = new Set();
  return {
    subscribe: (fn) => {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
    publish: (v) => {
      for (const fn of listeners) fn(v);
    },
  };
}

// BEFORE: a single context object forces every consumer to re-render on any change
{
  const appContext = channel();
  const renders = { themeBtn: 0, themePanel: 0, ticker: 0 };
  appContext.subscribe(() => renders.themeBtn++);
  appContext.subscribe(() => renders.themePanel++);
  appContext.subscribe(() => renders.ticker++);
  for (let tick = 1; tick <= 5; tick++) appContext.publish({ theme: "dark", ticker: tick });
  console.log(`BEFORE (single context): 5 ticker updates -> ${JSON.stringify(renders)}`);
}

// AFTER: split contexts — each consumer subscribes only to what it reads
{
  const themeCtx = channel();
  const tickerCtx = channel();
  const renders = { themeBtn: 0, themePanel: 0, ticker: 0 };
  themeCtx.subscribe(() => renders.themeBtn++);
  themeCtx.subscribe(() => renders.themePanel++);
  tickerCtx.subscribe(() => renders.ticker++);
  themeCtx.publish("dark");
  for (let tick = 1; tick <= 5; tick++) tickerCtx.publish(tick);
  console.log(`AFTER (split contexts): 1 theme set + 5 ticker updates -> ${JSON.stringify(renders)}`);
}

