function createCache({ ttl, now = () => Date.now() }) {
  const cache = new Map(); // key -> { data, expiresAt }
  return {
    async get(key, fetcher) {
      const hit = cache.get(key);
      if (hit && now() < hit.expiresAt) {
        console.log(`  [${key}] HIT (fresh) -> return cached`);
        return hit.data;
      }
      if (hit) {
        console.log(`  [${key}] HIT (stale) -> return stale, revalidating in background`);
        fetcher(key).then((data) => {
          cache.set(key, { data, expiresAt: now() + ttl });
          console.log(`  [${key}] background revalidation finished`);
        });
        return hit.data;
      }
      console.log(`  [${key}] MISS -> fetching`);
      const data = await fetcher(key);
      cache.set(key, { data, expiresAt: now() + ttl });
      return data;
    },
  };
}

async function main() {
  let t = 0;
  let fetchCalls = 0;
  const fakeFetch = async (key) => {
    fetchCalls++;
    return `${key}-v${fetchCalls}`;
  };
  const cache = createCache({ ttl: 1000, now: () => t });

  console.log("t=0    -> got", await cache.get("users", fakeFetch));
  t = 500;
  console.log("t=500  -> got", await cache.get("users", fakeFetch));
  t = 1500;
  console.log("t=1500 -> got", await cache.get("users", fakeFetch));
  await new Promise((r) => setTimeout(r, 20)); // let background revalidation land
  t = 1600;
  console.log("t=1600 -> got", await cache.get("users", fakeFetch));
  console.log("total fetch calls:", fetchCalls);
}

main();

