const parent = {
  Header: "App",
  SearchBar: "App",
  Main: "App",
  Footer: "App",
  Toolbar: "Main",
  DataTable: "Main",
  DetailPanel: "Main",
  App: null,
};

const reads = {
  query: ["SearchBar"],
  sortBy: ["Toolbar", "DataTable"],
  selectedId: ["DataTable", "DetailPanel"],
  theme: ["Header", "Footer"],
};

function ancestors(node) {
  const chain = [];
  while (node) {
    chain.push(node);
    node = parent[node];
  }
  return chain;
}

function lca(nodes) {
  const chains = nodes.map(ancestors);
  const [first, ...rest] = chains;
  return first.find((a) => rest.every((chain) => chain.includes(a)));
}

for (const [varName, readers] of Object.entries(reads)) {
  const place = lca(readers);
  const advice =
    readers.length === 1
      ? `COLOCATE in ${place} (only reader — no lifting needed)`
      : `LIFT to ${place} (lowest common ancestor)`;
  console.log(`${varName}: read by ${readers.join(", ")} -> ${advice}`);
}

